// Helper to check if a date is disabled according to picker options
self._isDateDisabled = function(date) {
    var opts = self._o;
    if (opts.minDate && date < opts.minDate) {
        return true;
    }
    if (opts.maxDate && date > opts.maxDate) {
        return true;
    }
    if (opts.disableWeekends && isWeekend(date)) {
        return true;
    }
    if (opts.disableDayFn && opts.disableDayFn(date)) {
        return true;
    }
    return false;
};

// Adjust date by skipping disabled days
self._adjustDateSkipDisabled = function(sign, days) {
    var newDate = self.getDate() || new Date();
    var increment = (sign === 'add') ? 1 : -1;
    for (var i = 0; i < days; i++) {
        do {
            newDate = new Date(newDate.valueOf() + increment * 24 * 60 * 60 * 1000);
        } while (self._isDateDisabled(newDate));
    }
    self.setDate(newDate);
};

self.el = document.createElement('div');

